import numpy as np

# The demo input and output show 4 different colored objects
# Let me analyze their exact shapes more carefully

demo_in_list = [list(row) for row in np.array(demo_in)]
demo_out_list = [list(row) for row in np.array(demo_out)]

print("=== DEMO INPUT OBJECTS ===")

# Extract each connected object with its color
def extract_objects(grid):
    objects = {}
    visited = set()

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0 and (r, c) not in visited:
                color = grid[r][c]
                obj = []
                stack = [(r, c)]
                visited.add((r, c))

                while stack:
                    cr, cc = stack.pop()
                    obj.append((cr, cc))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cr + dr, cc + dc
                        if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                            if grid[nr][nc] == color and (nr, nc) not in visited:
                                visited.add((nr, nc))
                                stack.append((nr, nc))
                objects[color] = obj

    return objects

def print_object(obj, bbox_width=5, title=""):
    print(f"\n{title}:")
    for r in range(bbox_height):
        row = []
        for c in range(bbox_width):
            if (r, c) in obj:
                row.append('■')
            else:
                row.append('.')
        print(''.join(row))

objects_in = extract_objects(demo_in_list)
objects_out = extract_objects(demo_out_list)

print("Input objects:")
for color, obj in sorted(objects_in.items()):
    rows = sorted(r for r,c in obj)
    cols = sorted(c for r,c in obj)
    top, left = min(rows), min(cols)
    h, w = max(rows) - top + 1, max(cols) - left + 1
    print(f"  Color {color}: size {h}x{w}, rows {rows}, rows present {[rows[0], rows[-1]]}, cols {cols}")
    # Print as grid
    grid_obj = [[' ' for _ in range(w)] for _ in range(h)]
    for r, c in obj:
        grid_obj[r-top][c-left] = color
    for row in grid_obj:
        print(f"    {row}")

print("\n\nOutput objects:")
for color, obj in sorted(objects_out.items()):
    rows = sorted(r for r,c in obj)
    cols = sorted(c for r,c in obj)
    top, left = min(rows), min(cols)
    h, w = max(rows) - top + 1, max(cols) - left + 1
    print(f"  Color {color}: size {h}x{w}, rows {rows}, rows present {[rows[0], rows[-1]]}, cols {cols}")
    grid_obj = [[' ' for _ in range(w)] for _ in range(h)]
    for r, c in obj:
        grid_obj[r-top][c-left] = color
    for row in grid_obj:
        print(f"    {row}")

