            print(f"\nLast 3 rows:")
            for i in range(max(0, len(sub)-3), len(sub)):
                row = sub[i]
                print(f"  Row {i}: {row[-30:]}{'...' if len(row) > 30 else ''}")

# Count colors
if isinstance(sub, list) and len(sub) > 0:
    colors = {}
    total_cells = 0
    for row in sub:
        if isinstance(row, list):
            for c in row:
                total_cells += 1
                if c != 0 and isinstance(c, int):
                    colors[int(c)] = colors.get(int(c), 0) + 1
    print(f"\nTotal cells: {total_cells}")
    print(f"Colors: {colors}")

